using System.ComponentModel;
using System.Net;
using System.Text;
using System.Text.Json;
using Microsoft.Extensions.AI;
using OpenAI;

// ---------------------------------------------------------------------------
// Configuration
// ---------------------------------------------------------------------------
var openAiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable before running.");

var model = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o-mini";

// ---------------------------------------------------------------------------
// Tools
// ---------------------------------------------------------------------------
var notebook = new Notebook();

var tools = new AIFunction[]
{
    AIFunctionFactory.Create(SearchWeb),
    AIFunctionFactory.Create(notebook.SaveNote),
    AIFunctionFactory.Create(notebook.ListNotes),
};

// ---------------------------------------------------------------------------
// Build the chat client with automatic function-calling support
// ---------------------------------------------------------------------------
IChatClient client = new OpenAIClient(openAiKey)
    .GetChatClient(model)
    .AsIChatClient()
    .AsBuilder()
    .UseFunctionInvocation()
    .Build();

var chatOptions = new ChatOptions { Tools = [.. tools] };

// ---------------------------------------------------------------------------
// Agent system prompt
// ---------------------------------------------------------------------------
var systemPrompt = """
    You are a research agent. The user will give you a topic to research.

    You have access to the following tools:
      • SearchWeb  – search the web for information on a query.
      • SaveNote   – save a key finding so you can reference it later.
      • ListNotes  – review all notes you have saved so far.

    Workflow:
      1. Break the topic into 2-3 focused search queries.
      2. For each query, call SearchWeb, read the results, and call SaveNote
         with the most important facts or quotes.
      3. After gathering enough information, call ListNotes to review your
         collected findings.
      4. Produce a well-structured summary for the user with sections,
         bullet points, and source references where possible.

    Be thorough but concise. Cite sources when available.
    """;

// ---------------------------------------------------------------------------
// Interactive loop
// ---------------------------------------------------------------------------
Console.WriteLine("╔══════════════════════════════════════╗");
Console.WriteLine("║       🔍  Research Agent  🔍        ║");
Console.WriteLine("╠══════════════════════════════════════╣");
Console.WriteLine("║  Enter a topic to research.         ║");
Console.WriteLine("║  Type 'quit' to exit.               ║");
Console.WriteLine("╚══════════════════════════════════════╝");
Console.WriteLine();

while (true)
{
    Console.ForegroundColor = ConsoleColor.Cyan;
    Console.Write("Research topic> ");
    Console.ResetColor();

    var topic = Console.ReadLine()?.Trim();
    if (string.IsNullOrEmpty(topic))
        continue;
    if (topic.Equals("quit", StringComparison.OrdinalIgnoreCase))
        break;

    notebook.Clear();

    List<ChatMessage> history =
    [
        new(ChatRole.System, systemPrompt),
        new(ChatRole.User, $"Please research the following topic and summarize your findings:\n\n{topic}"),
    ];

    Console.ForegroundColor = ConsoleColor.DarkGray;
    Console.WriteLine("\n⏳ Researching… (the agent will search the web and take notes)\n");
    Console.ResetColor();

    var response = await client.GetResponseAsync(history, chatOptions);

    Console.ForegroundColor = ConsoleColor.Green;
    Console.WriteLine("── Research Summary ─────────────────────────");
    Console.ResetColor();
    Console.WriteLine(response.Text);
    Console.WriteLine();
}

