// ---------------------------------------------------------------------------

/// <summary>
/// In-memory notebook that the agent uses to collect and review findings.
/// </summary>
sealed class Notebook
{
    private readonly List<(string Title, string Content)> _notes = [];

    [Description("Save a note capturing a key finding from your research.")]
    public string SaveNote(
        [Description("Short title for the note")] string title,
        [Description("The content / key facts to remember")] string content)
    {
        _notes.Add((title, content));
        Console.ForegroundColor = ConsoleColor.Magenta;
        Console.WriteLine($"  📝 Note saved: \"{title}\"");
        Console.ResetColor();
        return $"Note #{_notes.Count} saved: \"{title}\"";
    }

    [Description("List all notes saved so far during this research session.")]
    public string ListNotes()
    {
        if (_notes.Count == 0)
            return "No notes saved yet.";

        var sb = new StringBuilder();
        sb.AppendLine($"=== Research Notes ({_notes.Count} total) ===\n");
        for (int i = 0; i < _notes.Count; i++)
        {
            sb.AppendLine($"Note #{i + 1}: {_notes[i].Title}");
            sb.AppendLine(_notes[i].Content);
            sb.AppendLine();
        }
        return sb.ToString();
    }

    public void Clear() => _notes.Clear();
}

